import asyncio
import logging
import threading
import time


class EventLoopThread(threading.Thread):
    """
    Ensure all async operations are executed in separate thread
    """

    def __init__(self, *args, loop=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.loop = loop or asyncio.new_event_loop()
        self.running = False

    def run(self):
        self.running = True
        self.loop.run_forever()

    def run_coro(self, coro):
        return asyncio.run_coroutine_threadsafe(coro, loop=self.loop)

    def stop(self):
        def stop_event_loop():
            self.loop.call_soon_threadsafe(self.loop.stop)
            while self.loop.is_running():
                time.sleep(0.1)

        stop_event_loop()
        self.loop.close()
        self.join()
        self.running = False


class NotificationHandler():

    def __init__(self):
        self.notifications = []

    async def set_subscriber(self, notification):
        self.notifications.append(notification.head)

    def subscribe(self, callback):

        def restore(callback):
            callback(method='restore', parameters={})

        def subscribe_for_notifications(callback):
            callback(method='maintenance.subscribeForNotifications', parameters={})
        restore(callback)
        subscribe_for_notifications(callback)
        logging.info("Subscribed for notifications")

    def search_for_notifications(self, keys):
        for notification in self.notifications:
            try:
                output = notification.params
                for key in keys:
                    output = output.get(key)
                if output:
                    return output
            except AttributeError:
                continue

    def flush_notifications(self):
        self.notifications = []
